from dataclasses import dataclass

import pytest


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Area of the shape, rounded down to an int.

    Rect: w * h. Square: side * side. Tri: b * h / 2, floored.
    """
    match s:
        case Rect(w=w, h=h):
            return w * h
        case Square(side=side):
            return side * side
        case Tri(b=b, h=h):
            return b * h // 2


def test_rect_area() -> None:
    assert area(Rect(3, 4)) == 12


def test_rect_area_zero_width() -> None:
    assert area(Rect(0, 7)) == 0


def test_square_area() -> None:
    assert area(Square(5)) == 25


def test_tri_area_even_product() -> None:
    assert area(Tri(4, 3)) == 6


def test_tri_area_rounds_down() -> None:
    assert area(Tri(3, 3)) == 4


def test_tri_area_zero_height() -> None:
    assert area(Tri(10, 0)) == 0


@pytest.mark.parametrize(
    ("shape", "expected"),
    [
        (Rect(2, 2), 4),
        (Square(1), 1),
        (Tri(1, 1), 0),
    ],
)
def test_area_parametrized(shape: Shape, expected: int) -> None:
    assert area(shape) == expected
